#include <iostream>
#include <iomanip>
#include <string>

class Employee {
public:
    Employee(std::string first, std::string last, std::string ssn)
        : firstName(std::move(first)), lastName(std::move(last)), socialSecurityNumber(std::move(ssn)) {}
    virtual ~Employee() = default;

    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber;
    }
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
};

class CommissionEmployee : public Employee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn,
                       double sales, double rate)
        : Employee(std::move(first), std::move(last), std::move(ssn)),
          grossSales(sales), commissionRate(rate) {}

    double earnings() const override {
        return grossSales * commissionRate;
    }

    void print() const override {
        std::cout << "commission employee: ";
        Employee::print();
        std::cout << "\ngross sales: " << grossSales
                  << "; commission rate: " << commissionRate;
    }
private:
    double grossSales{0.0};
    double commissionRate{0.0};
};

class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary(salary) {}

    double earnings() const override {
        return baseSalary + CommissionEmployee::earnings();
    }

    void print() const override {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "; base salary: " << baseSalary;
    }
private:
    double baseSalary{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);
    BasePlusCommissionEmployee emp("Bob", "Lewis", "444-44-4444", 5000.0, 0.04, 300.0);
    emp.print();
    std::cout << "\nearned $" << emp.earnings() << '\n';
    return 0;
}

#include <iostream>
#include <iomanip>
#include <vector>
#include <string>

class Employee {
public:
    Employee(std::string name) : name_(std::move(name)) {}
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << "employee: " << name_;
    }
private:
    std::string name_;
};

class SalariedEmployee : public Employee {
public:
    SalariedEmployee(std::string name, double salary)
        : Employee(std::move(name)), weeklySalary_(salary) {}
    double earnings() const override { return weeklySalary_; }
    void print() const override {
        std::cout << "salaried ";
        Employee::print();
        std::cout << " | salary: " << weeklySalary_;
    }
private:
    double weeklySalary_{0.0};
};

class CommissionEmployee : public Employee {
public:
    CommissionEmployee(std::string name, double sales, double rate)
        : Employee(std::move(name)), sales_(sales), rate_(rate) {}
    double earnings() const override { return sales_ * rate_; }
    void print() const override {
        std::cout << "commission ";
        Employee::print();
        std::cout << " | sales: " << sales_ << ", rate: " << rate_;
    }
private:
    double sales_{0.0};
    double rate_{0.0};
};

void virtualViaPointer(const Employee* const ptr) {
    ptr->print();
    std::cout << " | earned: $" << ptr->earnings() << '\n';
}

void virtualViaReference(const Employee& ref) {
    ref.print();
    std::cout << " | earned: $" << ref.earnings() << '\n';
}

int main() {
    std::cout << std::fixed << std::setprecision(2);

    SalariedEmployee salaried("John Smith", 800.0);
    CommissionEmployee commission("Sue Jones", 10000.0, 0.06);

    std::cout << "--- Dynamic Binding via Pointers ---\n";
    std::vector<const Employee*> employees = {&salaried, &commission};
    for (const Employee* empPtr : employees) {
        virtualViaPointer(empPtr);
    }

    std::cout << "--- Dynamic Binding via References ---\n";
    for (const Employee* empPtr : employees) {
        virtualViaReference(*empPtr);
    }

    return 0;
}
